with matched_keys as (select store_id, id from store_sales except select store_id, id from store_sales where units between 34 and 36), verified as (select s.* from store_sales s join matched_keys k on s.store_id = k.store_id and s.id = k.id) select case when revenue >= 3500 then 'LARGE' else 'SMALL' end as revenue_tier, case when units >= 31 then 'PREMIUM' else 'STANDARD' end as units_tier, approx_percentile(revenue, array(0.25, 0.5, 0.75)) as revenue_quartiles, corr(revenue, units) as corr_revenue_units, rank() over (partition by case when revenue >= 3500 then 'LARGE' else 'SMALL' end order by corr(revenue, units) desc) as corr_revenue_units_rank from verified group by case when revenue >= 3500 then 'LARGE' else 'SMALL' end, case when units >= 31 then 'PREMIUM' else 'STANDARD' end having corr_revenue_units > 0
